@Component("rate-handler")
@ProcessingGroup("rate-processing-group")
public class RateEventHandler {
	
	// core constructor
	RateEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRateEvent
     */
    @EventHandler
    public void handle( CreateRateEvent event) {
        entityManager.persist(new Rate(event.getRateId(), event.getUnitPrice(), event.getRateCard(), event.getAdSlot(), event.getAdFormat(), event.getPricingModel()));
    }

    /*
     * @param	event UpdateRateEvent
     */
    @EventHandler
    public Rate handle( UpdateRateEvent event) {
    	entityManager.merge(new Rate(event.getRateId(), event.getUnitPrice(), event.getRateCard(), event.getAdSlot(), event.getAdFormat(), event.getPricingModel()));
    }
    
    /*
     * @param	event DeleteRateEvent
     */
    @EventHandler
    public void on( DeleteRateEvent event) {
    	Rate entity = new Rate();
   
    	// ------------------------------------------
    	// apply the RateId
    	// ------------------------------------------
    	entity.setRateId( event.getRateId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RateRepository rateEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RateEventHandler.class.getName());

}
